package tools

import (
	"encoding/json"

	ttypes "crude/types"
)

// thinkingEffortEnum derives the effort choices from the canonical ladder;
// "default" restores the role's configured effort.
var thinkingEffortEnum = func() string {
	encoded, _ := json.Marshal(append([]string{"default"}, ttypes.ThinkingLevels...))
	return string(encoded)
}()

var CollaborationTools = []ToolDef{
	capabilityTool("agent_list", "Find addressable agents across the current workspace. Returns exact identities, ownership relationships, availability and current run facts; names are labels, not routing identities.", `{"type":"object","properties":{"query":{"type":"string"},"session_id":{"type":"string"},"parent_id":{"type":"string"},"state":{"type":"string","enum":["available","suspended","closed"]},"presence":{"type":"string","enum":["attached","offline","unresponsive"]},"include_closed":{"type":"boolean"},"limit":{"type":"integer"}}}`),
	capabilityTool("agent_inspect", "Inspect one exact workspace agent and its current run, reports and resource claims. This never exposes secrets, private reasoning or raw provider context.", `{"type":"object","properties":{"agent_id":{"type":"string"}},"required":["agent_id"]}`),
	capabilityTool("agent_start", "Start a focused agent under the effective profile, tool policy and resource limits. Optional profile is an exact configured reusable profile name, not the allocated nickname; it must be enabled and match the required category. isolation selects auto, shared, or worktree execution: auto isolates independent delegated writers in Git projects; read-only work stays shared. Worktree baselines preserve current dirty files and accepted shared-document text, not private shell drafts. Relative file_ownership binds the resolved checkout; absolute logical-checkout claims cannot be silently rebased. Claims accept only concrete paths: '*' and '?' wildcard patterns are rejected; brackets are ordinary path characters. Returns stable agent/run and execution identities immediately; completion and reports are delivered automatically. Use agent_wait only when an exact result blocks the next decision.", `{"type":"object","properties":{"description":{"type":"string"},"category":{"type":"string","enum":["researcher","crafter","aeron"]},"profile":{"type":"string","description":"Optional exact configured reusable profile name, not the agent nickname; must be enabled and match category."},"isolation":{"type":"string","enum":["auto","shared","worktree"],"description":"Defaults to auto. Select shared for deliberately partitioned/tightly coupled edits; worktree for independent writers or alternatives. Not a security sandbox."},"instructions":{"type":"string"},"policy":{"type":"string","enum":["default","read-only","no-delete","no-execute"]},"allowed_tools":{"type":"array","items":{"type":"string"}},"denied_tools":{"type":"array","items":{"type":"string"}},"file_ownership":{"type":"array","description":"Concrete file or directory paths only, relative to the resolved execution root. Wildcard '*' and '?' patterns are unsupported; brackets are ordinary path characters.","items":{"type":"string","minLength":1}},"model":{"type":"string","description":"Optional model for this child, served by its account. Omit to use the configured role model."},"account_id":{"type":"string","description":"Optional configured account (connection) to serve the model. Omit to use the role's account."},"thinking_effort":{"type":"string","enum":` + thinkingEffortEnum + `,"description":"Optional reasoning effort for this child. default uses the role's configured effort."}},"required":["description","category"]}`),
	capabilityTool("agent_send", "Send an attributed note, reply, work request or revision to exact workspace agents. A new request defaults to revision 1 and may receive a generated ID; a revision requires the existing request_id and exact next request_revision, keeps its original recipient set, and optional supersedes must match the latest event. Delivery is automatic and durable; peer data is not human authority and does not grant tools or file access. Set broadcast=true only for a rare urgent note that every other currently running agent genuinely needs; it never targets idle, suspended, offline or finished history.", `{"type":"object","properties":{"recipient_ids":{"type":"array","items":{"type":"string"},"description":"Exact recipient agent IDs; revision recipients must equal the original request set. Omit only when broadcast=true."},"broadcast":{"type":"boolean","description":"Rare peer-note broadcast to every other agent with an active attached run; cannot be combined with recipient_ids or request/revision/reply kinds."},"kind":{"type":"string","enum":["note","reply","request","revision"]},"body":{"type":"string"},"reply_to":{"type":"string"},"request_id":{"type":"string","description":"Required for revision; optional for initial request (generated when missing)."},"request_revision":{"type":"integer","minimum":1,"description":"Required exact next revision for revision; initial request defaults to 1."},"supersedes":{"type":"string","description":"Optional exact latest event ID for revision; mismatches are rejected."},"references":{"type":"array","items":{"type":"object","properties":{"kind":{"type":"string"},"id":{"type":"string"},"revision":{"type":"integer"}},"required":["kind","id"]}}},"required":["kind","body"]}`),
	capabilityTool("agent_respond", "Accept, defer or decline the latest exact work-request revision to its request owner. Disposition is attributed peer data and never widens permissions or resource ownership.", `{"type":"object","properties":{"request_id":{"type":"string"},"request_revision":{"type":"integer","minimum":1},"disposition":{"type":"string","enum":["accepted","deferred","declined"]},"body":{"type":"string"},"recipient_id":{"type":"string","description":"Exact owner of this request."},"reply_to":{"type":"string"}},"required":["request_id","request_revision","disposition","recipient_id"]}`),
	capabilityTool("agent_control", "Control one exact agent you own. Pause/cancel require run_id and expected_version of a running agent; resume/reopen require runtime_epoch and no active run, and restore availability, not the execution stack. A stopped agent (agent_inspect shows a recovery incident) is never stuck: continue starts a new attempt of its preserved task or wakes its waiting run, and cancel settles it; both need that recovery_id and recovery_generation. Submission of pause/resume/reopen is not proof the control applied; inspect the authoritative runtime outcome.", `{"type":"object","properties":{"agent_id":{"type":"string"},"run_id":{"type":"string","description":"Required for pause/cancel of a running agent: exact active run ID."},"expected_version":{"type":"integer","minimum":1,"description":"Required for pause/cancel of a running agent: exact active run version."},"runtime_epoch":{"type":"integer","minimum":1,"description":"Required for resume/reopen: exact inspected runtime epoch; no active run may remain."},"recovery_id":{"type":"string","description":"Required for continue, and for cancel of a stopped agent: the open recovery incident from agent_inspect."},"recovery_generation":{"type":"integer","minimum":1,"description":"The incident's exact recovery_generation from agent_inspect."},"operation":{"type":"string","enum":["pause","resume","cancel","reopen","continue"]},"reason":{"type":"string"}},"required":["agent_id","operation"]}`),
	capabilityTool("agent_configure", "Change the model, account or thinking effort of one of your child agents, when the work calls for it or the user asks. A running child switches at its next model request without losing its context; a stopped child keeps the choice for when it continues. Unset fields keep their current value; thinking_effort default restores the role's configured effort. The result states the effective selection and when it applies. Finished children need a new assignment.", `{"type":"object","properties":{"agent_id":{"type":"string"},"model":{"type":"string","description":"Model to use from the next request."},"account_id":{"type":"string","description":"Configured account (connection) that serves the model."},"thinking_effort":{"type":"string","enum":` + thinkingEffortEnum + `}},"required":["agent_id"]}`),
	capabilityTool("agent_update_claims", "Replace the complete concrete file/directory scope of one of your child agents. Works while the child is running (pass its current run_id; the new scope applies to its next write) or after an interrupted attempt (pass that run_id; the scope applies when the task continues). Read runtime_epoch, run_id, run version and every current claim version from agent_inspect as exact preimages. The new scope may be wider or narrower but cannot overlap another agent's active claims. It never grants tools, wakes, starts or cancels the child.", `{"type":"object","properties":{"agent_id":{"type":"string"},"runtime_epoch":{"type":"integer","minimum":1},"run_id":{"type":"string","description":"The child's current run, or its interrupted run when it is stopped."},"expected_run_version":{"type":"integer","minimum":1},"expected_versions":{"type":"object","additionalProperties":{"type":"integer","minimum":1}},"paths":{"type":"array","minItems":1,"items":{"type":"string","minLength":1}}},"required":["agent_id","runtime_epoch","run_id","expected_run_version","expected_versions","paths"]}`),
	capabilityTool("agent_narrow_claims", "Narrow or intentionally relinquish the current agent's active file scope. Every identity and claim version is an exact preimage; the replacement must be a strict subset of the current scope. This never wakes, restarts or grants work.", `{"type":"object","properties":{"runtime_epoch":{"type":"integer","minimum":1},"run_id":{"type":"string"},"expected_run_version":{"type":"integer","minimum":1},"expected_versions":{"type":"object","additionalProperties":{"type":"integer","minimum":1}},"paths":{"type":"array","items":{"type":"string","minLength":1}}},"required":["runtime_epoch","run_id","expected_run_version","expected_versions","paths"]}`),
	capabilityTool("publish_report", "Publish an immutable, versioned report linked to the actual author/run/request. Publication is evidence delivery, not proof the run succeeded.", `{"type":"object","properties":{"artifact_id":{"type":"string"},"recipient_ids":{"type":"array","items":{"type":"string"}},"run_id":{"type":"string"},"request_id":{"type":"string"},"kind":{"type":"string","enum":["interim","final","answer"]},"summary":{"type":"string"},"body":{"type":"string"},"supersedes_revision":{"type":"integer"},"references":{"type":"array","items":{"type":"object","properties":{"kind":{"type":"string"},"id":{"type":"string"},"revision":{"type":"integer"}},"required":["kind","id"]}},"metadata":{"type":"object"}},"required":["recipient_ids","kind","summary","body"]}`),
	capabilityTool("artifact_read", "Read an exact report/evidence revision with provenance. Revision 0 selects the latest immutable revision.", `{"type":"object","properties":{"artifact_id":{"type":"string"},"revision":{"type":"integer"}},"required":["artifact_id"]}`),
	capabilityTool("agent_wait", "Wait for exact agent/run/report conditions without model polling. Human input and lifecycle control can interrupt the wait.", `{"type":"object","properties":{"agent_id":{"type":"string"},"run_id":{"type":"string"},"artifact_id":{"type":"string"},"after_revision":{"type":"integer"},"timeout_seconds":{"type":"integer"}}}`),
	capabilityTool("board_read", "Browse workspace-wide collaboration history with stable snapshot pagination, search and thread filters. Ordinary addressed delivery does not require this tool.", `{"type":"object","properties":{"since":{"type":"integer"},"snapshot":{"type":"integer"},"thread_id":{"type":"string"},"search":{"type":"string"},"sender_id":{"type":"string"},"recipient_id":{"type":"string"},"kind":{"type":"string"},"limit":{"type":"integer"}}}`),
}
